import{_ as e,c as o,o as r,ah as s}from"./chunks/framework.RCw5T9E9.js";const c=JSON.parse('{"title":"Export and import","description":"","frontmatter":{"title":"Export and import"},"headers":[],"relativePath":"logs/export.md","filePath":"logs/export.md"}'),n={name:"logs/export.md"};function a(i,t,l,h,d,g){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="export-and-import" tabindex="-1">Export and import <a class="header-anchor" href="#export-and-import" aria-label="Permalink to &quot;Export and import&quot;">​</a></h1><p>Events from the <strong>Logs</strong> tab can be saved to a file and opened again — in Vue Inspector or, for <strong>HTML</strong>, in any browser. This is useful for bug reports, for sharing a scenario with colleagues and for analysis outside the page.</p><p>General information about the tab: <a href="./general.html">Working with logs</a>.</p><hr><h2 id="export-format" tabindex="-1">Export format <a class="header-anchor" href="#export-format" aria-label="Permalink to &quot;Export format&quot;">​</a></h2><p>The format is set in <strong>Options → Logs → Export</strong> and applies to every export from the tab:</p><table tabindex="0"><thead><tr><th>Format</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>HTML</strong> (default)</td><td>Static report that opens in any browser and can be imported back</td></tr><tr><td><strong>JSON</strong></td><td>Raw events for re-import or for tools</td></tr></tbody></table><p><strong>Export Logs</strong> downloads the file in the selected format right away.</p><hr><h2 id="what-is-exported" tabindex="-1">What is exported <a class="header-anchor" href="#what-is-exported" aria-label="Permalink to &quot;What is exported&quot;">​</a></h2><h3 id="export-logs" tabindex="-1">Export Logs <a class="header-anchor" href="#export-logs" aria-label="Permalink to &quot;Export Logs&quot;">​</a></h3><ul><li>Without a selection — all events visible in the table after <strong>Search</strong> and <strong>Type</strong> filters.</li><li>With a selection — only the rows ticked in the checkbox column; the button shows <strong>Export Logs (n)</strong>.</li></ul><p>The button is disabled while the filtered list is empty.</p><h3 id="single-event" tabindex="-1">Single event <a class="header-anchor" href="#single-event" aria-label="Permalink to &quot;Single event&quot;">​</a></h3><p><strong>Export event</strong> in the <strong>⋮</strong> menu of the details header or in the row context menu exports one event.</p><p>For network events the item is called <strong>Export request &amp; response</strong>: the <strong>Send request</strong> and <strong>Receive response</strong> events of the same request are exported together in one file, so the request and its response are never separated.</p><p>Single-event exports use the same format setting as <strong>Export Logs</strong>.</p><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Export</th><th>File name</th></tr></thead><tbody><tr><td><strong>Export Logs</strong></td><td><code>logs_&lt;date&gt;_&lt;time&gt;.html</code> / <code>.json</code></td></tr><tr><td>Network pair</td><td><code>log_network_&lt;date&gt;_&lt;time&gt;.html</code> / <code>.json</code></td></tr><tr><td>Other single event</td><td><code>log_&lt;type&gt;_&lt;date&gt;_&lt;time&gt;.html</code> / <code>.json</code></td></tr></tbody></table><p>Data is masked at capture time, so the files contain the same masked values as the view (see <a href="./settings.html#data-masking">Logs settings</a>).</p><hr><h2 id="html-report" tabindex="-1">HTML report <a class="header-anchor" href="#html-report" aria-label="Permalink to &quot;HTML report&quot;">​</a></h2><p>The <strong>HTML</strong> report is one self-contained file: styles, script, the application icon and the event data are embedded. It uses a dark theme, does not load external resources and opens offline from disk.</p><h3 id="sidebar" tabindex="-1">Sidebar <a class="header-anchor" href="#sidebar" aria-label="Permalink to &quot;Sidebar&quot;">​</a></h3><ul><li><strong>Report</strong> — <strong>Overview</strong> and <strong>All events</strong> with the total count;</li><li>sections by type with counters: <strong>Network</strong> (<strong>Send request</strong>, <strong>Receive response</strong>), <strong>Components</strong> (<strong>Change props</strong>, <strong>Emit</strong>), <strong>Pinia</strong> (<strong>Change store</strong>, <strong>Store action</strong>), <strong>Page</strong> (<strong>Navigation</strong>, <strong>JS error</strong>);</li><li><strong>Download Vue Inspector</strong> at the bottom — link to the project page.</li></ul><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Summary cards: <strong>Events</strong>, <strong>Errors</strong>, <strong>Failed requests</strong>, first and last event time, time span; counters by type; export information.</p><p><strong>Events</strong>, <strong>Errors</strong> and <strong>Failed requests</strong> are clickable: they open <strong>All events</strong> with the matching filter. The active filter is shown as a chip above the list; clicking the chip removes it.</p><h3 id="event-list-and-details" tabindex="-1">Event list and details <a class="header-anchor" href="#event-list-and-details" aria-label="Permalink to &quot;Event list and details&quot;">​</a></h3><ul><li>Search in the top bar; with <strong>in data</strong> enabled the search also looks inside event data.</li><li>Clicking a row opens details with the same tabs as in the app (<strong>Overview</strong>, <strong>Params</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Changes</strong>, <strong>Before</strong> / <strong>After</strong>, <strong>Raw</strong>, etc.).</li><li>For network events, the button next to <strong>Close</strong> jumps between the request and its response.</li><li><strong>↑ / ↓</strong> move between events, <strong>Esc</strong> closes details.</li><li>The selected section and event are kept in the address (<code>#…</code>), so a link to a specific event can be shared and survives a reload.</li></ul><hr><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p><strong>Import Logs</strong> opens a file exported from the <strong>Logs</strong> tab — <strong>JSON</strong> or <strong>HTML</strong>.</p><ul><li>Imported events are shown in a separate read-only view. The banner shows the file name, the number of events and the export time.</li><li><strong>Back to live logs</strong> returns to live recording; live events are not lost while a file is open.</li><li>Invalid events are skipped (the number is shown in the import message).</li><li>HTML files that are not a Logs report are rejected with a message.</li><li>Imported data goes through the current masking settings once more.</li></ul><p>Files with full network entries from earlier versions also open: details show only the sections of the event&#39;s own type.</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./general.html">Working with logs</a></li><li><a href="./settings.html">Logs settings</a></li><li><a href="/qa-tools/docs/network/export.html">Export collections</a></li></ul>',38)])])}const m=e(n,[["render",a]]);export{c as __pageData,m as default};
